def transform(grid):
    h, w = len(grid), len(grid[0])
    g = [row[:] for row in grid]

    sep_rows = [r for r in range(h) if all(v == 8 for v in grid[r])]
    sep_cols = [c for c in range(w) if all(grid[r][c] == 8 for r in range(h))]

    def bands(size, separators):
        result = []
        start = 0
        for s in separators:
            if start < s:
                result.append((start, s))
            start = s + 1
        if start < size:
            result.append((start, size))
        return result

    rb = bands(h, sep_rows)
    cb = bands(w, sep_cols)

    def band_index(pos, intervals):
        for i, (a, b) in enumerate(intervals):
            if a <= pos < b:
                return i
        return None

    markers = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color not in (0, 8):
                markers.append((color, band_index(r, rb), band_index(c, cb)))

    paths = []
    for i, (color, r1, c1) in enumerate(markers):
        for color2, r2, c2 in markers[i + 1:]:
            if color != color2:
                continue
            if r1 == r2 and c1 != c2:
                paths.append((color, [(r1, c) for c in range(min(c1, c2), max(c1, c2) + 1)]))
            elif c1 == c2 and r1 != r2:
                paths.append((color, [(r, c1) for r in range(min(r1, r2), max(r1, r2) + 1)]))

    cell_colors = {}
    for color, cells in paths:
        for cell in cells:
            cell_colors.setdefault(cell, set()).add(color)

    for (ri, ci), colors in cell_colors.items():
        color = 6 if len(colors) > 1 else next(iter(colors))
        r0, r1 = rb[ri]
        c0, c1 = cb[ci]
        for r in range(r0, r1):
            for c in range(c0, c1):
                g[r][c] = color

    return g
